        execSync('git config user.email "test@test.com"', { cwd: testDir, stdio: 'pipe' });
        execSync('git config user.name "Test"', { cwd: testDir, stdio: 'pipe' });
        await fs.writeFile(path.join(testDir, 'README.md'), '# Test');
