const fs = require('node:fs/promises');
const path = require('node:path');
const { execSync } = require('node:child_process');

async function test() {
  const testDir = '/tmp/kspec-merge-test-' + Date.now();
  await fs.mkdir(testDir, { recursive: true });

  // Init git
  execSync('git init', { cwd: testDir, stdio: 'pipe' });
  execSync('git config user.email \"test@test.com\"', { cwd: testDir, stdio: 'pipe' });
  execSync('git config user.name \"Test\"', { cwd: testDir, stdio: 'pipe' });
  await fs.writeFile(path.join(testDir, 'README.md'), '# Test');
  execSync('git add . && git commit -m \"initial\"', { cwd: testDir, stdio: 'pipe' });

  // Create bin wrapper
  const binDir = path.join(testDir, '_bin');
  await fs.mkdir(binDir, { recursive: true });
  const projectCli = path.resolve('/workspace/dist/cli/index.js');
  await fs.writeFile(
    path.join(binDir, 'kspec'),
    '#!/usr/bin/env node\nrequire(\"' + projectCli + '\");\n',
    { mode: 0o755 },
  );

  // Add to PATH
  process.env.PATH = binDir + ':' + process.env.PATH;

  // Test which
  try {
    const result = execSync('which kspec', { encoding: 'utf-8', stdio: ['pipe', 'pipe', 'pipe'] });
    console.log('which kspec:', result.trim());
  } catch (e) {
    console.log('which kspec failed:', e.message);
  }

  // Test running it
  try {
    const result = execSync('kspec --version', { encoding: 'utf-8', stdio: ['pipe', 'pipe', 'pipe'] });
    console.log('kspec --version:', result.trim());
  } catch (e) {
