        await initializeShadow(testDir);

        const worktreeDir = path.join(testDir, SHADOW_WORKTREE_DIR);

        // Try to pull with non-existent remote configured
        const result = await shadowPull(worktreeDir, {
          remote: 'specs-origin',
          remoteType: 'named',
