      // Meta should still exist
      const metaExists = await fs
        .access(metaPath)
        .then(() => true)
        .catch(() => false);

      expect(metaExists).toBe(true);

      // loadSessionContext should return empty context
      const context = await loadSessionContext(ctx);
      expect(context.focus).toBeNull();
    });
  });
