    10→import {
    11→  type EnvInjectionResult,
    12→  createSessionWithBudget,
    13→  validateSessionId,
    14→  injectClaudeCodeEnv,
    15→  injectCodexEnv,
    16→  injectGeminiEnv,
    17→  injectOpenCodeEnv,
    18→  getFallbackInjectionInstructions,
    19→} from "../../../sessions/store.js";
    20→import { ulid } from "ulid";
    21→import { EXIT_CODES } from "../../exit-codes.js";
    22→import { error, info, output, success, warn } from "../../output.js";
    23→
    24→/**
    25→ * Detect agent harness and perform environment injection.
    26→ *
    27→ * AC: @session-creation-and-env-injection ac-inject-claude
    28→ * AC: @session-creation-and-env-injection ac-inject-codex
    29→ * AC: @session-creation-and-env-injection ac-inject-fallback
    30→ */
    31→async function performEnvInjection(
    32→  sessionId: string,
    33→): Promise<EnvInjectionResult> {
    34→  // Detect Claude Code
    35→  if (
    36→    process.env.CLAUDECODE === "1" ||
    37→    process.env.CLAUDE_CODE_ENTRYPOINT ||
    38→    process.env.CLAUDE_PROJECT_DIR
    39→  ) {
    40→    return injectClaudeCodeEnv(sessionId);
    41→  }
    42→
    43→  // Detect Codex CLI
    44→  if (process.env.CODEX_SANDBOX) {
    45→    return injectCodexEnv(sessionId);
    46→  }
    47→
    48→  // Detect Gemini CLI
    49→  if (process.env.GEMINI_CLI === "1") {
    50→    return injectGeminiEnv(sessionId);
    51→  }
    52→
    53→  // Detect OpenCode
    54→  if (process.env.OPENCODE_CONFIG_DIR || process.env.OPENCODE_CONFIG) {
    55→    return injectOpenCodeEnv(sessionId);
    56→  }
    57→
    58→  // Fallback for unknown harnesses
    59→  return getFallbackInjectionInstructions(sessionId);
    60→}
    61→
    62→/**
    63→ * Action handler for `kspec session create`.
    64→ *
    65→ * Creates a new session with optional budget and environment injection.
    66→ *
    67→ * AC: @session-creation-and-env-injection ac-create
    68→ * AC: @session-creation-and-env-injection ac-budget
    69→ * AC: @session-creation-and-env-injection ac-budget-local
    70→ * AC: @session-creation-and-env-injection ac-inject-claude
    71→ * AC: @session-creation-and-env-injection ac-inject-codex
    72→ * AC: @session-creation-and-env-injection ac-inject-fallback
    73→ *
    74→ * Exit codes documented per @trait-semantic-exit-codes ac-8:
    75→ * - 0: Session created successfully
    76→ * - 1: Validation error (invalid budget value)
    77→ * - 3: Runtime error (filesystem failure)
    78→ */
    79→export async function sessionCreateAction(options: {
    80→  agentType: string;
    81→  budget?: string;
    82→  inject?: boolean;
    83→  taskId?: string;
    84→}): Promise<void> {
    85→  try {
    86→    const ctx = await initContext();
    87→
    88→    // AC: @session-creation-and-env-injection ac-invalid-session
    89→    // Validate existing KSPEC_SESSION_ID if set — warn user if it's stale/corrupt
    90→    const existingSessionId = process.env.KSPEC_SESSION_ID;
    91→    if (existingSessionId) {
    92→      const validation = await validateSessionId(ctx.specDir, existingSessionId);
    93→      if (!validation.valid) {
    94→        warn(
    95→          `Current KSPEC_SESSION_ID (${existingSessionId}) is invalid: ${validation.error}`,
    96→        );
    97→        info(validation.suggestion || "Creating a new session will generate a fresh ID.");
    98→      }
    99→    }
   100→
   101→    // Validate budget if provided
   102→    // AC: @trait-error-guidance ac-5 - indicate which field/value failed
   103→    let budgetNum: number | undefined;
   104→    if (options.budget !== undefined) {
   105→      // Use Number() instead of parseInt to reject "3.5", "3abc", "1e2" etc.
   106→      budgetNum = Number(options.budget);
   107→      if (isNaN(budgetNum) || budgetNum <= 0 || !Number.isInteger(budgetNum) || !/^\d+$/.test(options.budget)) {
   108→        // AC: @trait-error-guidance ac-2, ac-5 - include suggested action and field info
   109→        // AC: @trait-error-guidance ac-6 - guidance included in structured error
   110→        error(
   111→          `Invalid budget value: "${options.budget}". Must be a positive integer.`,
   112→          { suggestion: "Usage: kspec session create --budget <positive-integer>" },
   113→        );
   114→        process.exit(EXIT_CODES.USAGE_ERROR);
   115→      }
   116→    }
   117→
   118→    // Generate session ID
   119→    const sessionId = ulid();
   120→
   121→    // AC: @session-creation-and-env-injection ac-create, ac-budget, ac-budget-local
   122→    const result = await createSessionWithBudget(ctx.specDir, {
   123→      id: sessionId,
   124→      agent_type: options.agentType,
   125→      task_id: options.taskId,
   126→      budget: budgetNum,
   127→    });
   128→
   129→    // Handle environment injection if requested
   130→    let injection: EnvInjectionResult | null = null;
   131→    if (options.inject) {
   132→      injection = await performEnvInjection(sessionId);
   133→    }
   134→
   135→    // Build output data
   136→    const outputData: Record<string, unknown> = {
   137→      session_id: result.session_id,
   138→      agent_type: result.session.agent_type,
   139→      status: result.session.status,
   140→      started_at: result.session.started_at,
   141→    };
   142→
   143→    if (result.session.task_id) {
   144→      outputData.task_id = result.session.task_id;
   145→    }
   146→
   147→    if (result.budget) {
   148→      outputData.budget = {
   149→        max_per_cycle: result.budget.max_per_cycle,
   150→        started_this_cycle: result.budget.started_this_cycle,
   151→      };
   152→    }
   153→
   154→    if (injection) {
   155→      outputData.env_injection = {
   156→        method: injection.method,
   157→        injected: injection.injected,
   158→        description: injection.description,
   159→        ...(injection.path ? { path: injection.path } : {}),
   160→      };
   161→    }
   162→
   163→    // AC: @trait-json-output ac-1, ac-2, ac-5 - JSON with all data, ISO timestamps
   164→    output(outputData, () => {
