     4→ * All types used across session sub-modules live here to prevent circular dependencies.
     5→ */
     6→
     7→import type { ObservationType } from "../../../schema/index.js";
     8→import type { GitWorkingTree } from "../../../utils/index.js";
     9→import type { SessionContext as StoredSessionContext } from "../../../schema/index.js";
    10→
    11→// ─── Session Start Types ────────────────────────────────────────────────────
    12→
    13→export interface SessionStartContext {
    14→  /** When this context was generated */
    15→  generated_at: string;
    16→
    17→  /** Current git branch */
    18→  branch: string | null;
    19→
    20→  /** Session context (focus, threads, questions) */
    21→  context: StoredSessionContext | null;
    22→
    23→  /** Tasks currently in progress */
    24→  active_tasks: ActiveTaskSummary[];
    25→
    26→  /** Tasks awaiting review (code done, PR pending) */
    27→  pending_review_tasks: ActiveTaskSummary[];
    28→
    29→  /** Recent notes from active tasks */
    30→  recent_notes: NoteSummary[];
    31→
    32→  /** Incomplete todos from active tasks */
    33→  active_todos: TodoSummary[];
    34→
    35→  /** Tasks ready to be picked up */
    36→  ready_tasks: ReadyTaskSummary[];
    37→
    38→  /** Blocked tasks with blockers */
    39→  blocked_tasks: BlockedTaskSummary[];
    40→
    41→  /** Recently completed tasks */
    42→  recently_completed: CompletedTaskSummary[];
    43→
    44→  /** Recent git commits */
    45→  recent_commits: CommitSummary[];
    46→
    47→  /** Unified activity timeline (merged tasks + commits, deduplicated) */
    48→  activity_timeline: ActivityItem[];
    49→
    50→  /** Working tree status */
    51→  working_tree: GitWorkingTree | null;
    52→
    53→  /** Inbox items awaiting triage (oldest first) */
    54→  inbox_items: InboxSummary[];
    55→
    56→  /** Inbox triage statistics */
    57→  inbox_stats: InboxStats;
    58→
    59→  /** Unresolved observations (full mode only) */
    60→  observations: ObservationSummary[];
    61→
    62→  /** Summary statistics */
    63→  stats: SessionStats;
    64→
    65→  /** Computed/derived fields aggregating other context data */
    66→  computed: SessionContextComputed;
    67→}
    68→
    69→export interface ActiveTaskSummary {
    70→  ref: string;
    71→  slug: string | null;
    72→  title: string;
    73→  description: string | null;
    74→  status: "in_progress" | "needs_work" | "pending_review";
    75→  started_at: string | null;
    76→  priority: number;
    77→  spec_ref: string | null;
    78→  note_count: number;
    79→  last_note_at: string | null;
    80→  todo_count: number;
    81→  incomplete_todos: number;
    82→}
    83→
    84→export interface NoteSummary {
    85→  task_ref: string;
    86→  task_title: string;
    87→  task_status: "in_progress" | "pending_review" | "needs_work" | "completed";
    88→  note_ulid: string;
    89→  created_at: string;
    90→  author: string | null;
    91→  content: string;
    92→}
    93→
    94→export interface TodoSummary {
    95→  task_ref: string;
    96→  task_title: string;
    97→  id: number;
    98→  text: string;
    99→  added_at: string;
   100→  added_by: string | null;
   101→}
   102→
   103→export interface ReadyTaskSummary {
   104→  ref: string;
   105→  slug: string | null;
   106→  title: string;
   107→  description: string | null;
   108→  priority: number;
   109→  spec_ref: string | null;
   110→  tags: string[];
   111→  unlocks: number;
   112→}
   113→
   114→export interface BlockedTaskSummary {
   115→  ref: string;
   116→  slug: string | null;
   117→  title: string;
   118→  description: string | null;
   119→  blocked_by: string[];
   120→  unmet_deps: string[];
   121→  unlocks: number;
   122→}
   123→
   124→export interface CompletedTaskSummary {
   125→  ref: string;
   126→  slug: string | null;
   127→  title: string;
   128→  completed_at: string;
   129→  closed_reason: string | null;
   130→  origin?: "manual" | "derived" | "observation_promotion";
   131→}
   132→
   133→export interface CommitSummary {
   134→  hash: string;
   135→  full_hash: string;
   136→  date: string;
   137→  message: string;
   138→  author: string;
   139→  task_refs: string[];
   140→}
   141→
   142→/**
   143→ * A single entry in the unified activity timeline.
   144→ * Merges completed tasks and git commits into a chronological view.
   145→ * Commits linked to tasks via Task: @slug trailer are deduplicated into combined entries.
   146→ */
   147→export type ActivityItem =
   148→  | { type: "task_completion"; date: string; task: CompletedTaskSummary }
   149→  | { type: "commit"; date: string; commit: CommitSummary }
   150→  | {
   151→      type: "linked_commit";
   152→      date: string;
   153→      commit: CommitSummary;
   154→      task: CompletedTaskSummary;
   155→    };
   156→
   157→export interface SessionStats {
   158→  total_tasks: number;
   159→  in_progress: number;
   160→  needs_work: number;
   161→  pending_review: number;
   162→  ready: number;
   163→  blocked: number;
   164→  completed: number;
   165→  inbox_items: number;
   166→}
   167→
   168→/**
   169→ * Computed/derived fields for JSON consumers.
   170→ * Aggregates data from other session context fields into a single
   171→ * convenient object. Raw source arrays are preserved unchanged.
   172→ */
   173→export interface SessionContextComputed {
   174→  /** Count of inbox items with no triage record */
   175→  inbox_untriaged_count: number;
   176→  /** Count of inbox items triaged with 'defer' action */
   177→  inbox_deferred_count: number;
   178→  /** Total inbox item count */
   179→  inbox_total: number;
   180→  /** Map of task ref (short ULID) to count of pending tasks it unblocks */
   181→  task_unlocks: Record<string, number>;
   182→  /** Unified activity timeline (same as activity_timeline, for computed namespace) */
   183→  recent_activity: ActivityItem[];
   184→}
   185→
   186→export interface InboxSummary {
   187→  ref: string;
   188→  text: string;
   189→  created_at: string;
   190→  tags: string[];
   191→  added_by: string | null;
   192→  triaged: boolean;
   193→  triage_action: string | null;
   194→}
   195→
   196→export interface InboxStats {
   197→  total: number;
   198→  untriaged: number;
   199→  deferred: number;
   200→  triaged: number;
   201→}
   202→
   203→export interface ObservationSummary {
   204→  ref: string;
   205→  type: ObservationType;
   206→  content: string;
   207→  created_at: string;
   208→  author: string | null;
   209→  resolved: boolean;
   210→  workflow_ref: string | null;
   211→}
   212→
   213→export interface SessionOptions {
   214→  brief?: boolean;
   215→  full?: boolean;
   216→  since?: string;
   217→  git?: boolean;
   218→  limit?: string;
   219→  eligible?: boolean; // Only include automation-eligible tasks in ready_tasks
   220→}
   221→
   222→// ─── Checkpoint Types ───────────────────────────────────────────────────────
   223→
   224→export interface CheckpointResult {
   225→  /** Whether session can end cleanly */
   226→  ok: boolean;
   227→
   228→  /** Human-readable message for Claude Code */
   229→  message: string;
   230→
   231→  /** Issues that need attention before stopping */
   232→  issues: CheckpointIssue[];
   233→
   234→  /** Instructions for the agent */
   235→  instructions: string[];
   236→}
   237→
   238→export interface CheckpointIssue {
   239→  type: "uncommitted_changes" | "in_progress_task" | "incomplete_todo";
   240→  description: string;
   241→  details?: Record<string, unknown>;
   242→}
   243→
   244→export interface CheckpointOptions {
   245→  force?: boolean;
   246→  /** Set when stop hook is already active (retry after previous block) */
   247→  stopHookActive?: boolean;
   248→}
   249→
   250→/** Claude Code hook input for Stop hooks */
   251→export interface StopHookInput {
   252→  session_id?: string;
   253→  transcript_path?: string;
   254→  hook_event_name?: string;
   255→  stop_hook_active?: boolean;
   256→}
   257→
   258→// ─── Iteration Stats Types ──────────────────────────────────────────────────
   259→
   260→/**
   261→ * Stats for tasks completed/started within a time window.
   262→ * Used by ralph to track task completions per iteration.
   263→ */
   264→export interface IterationStats {
   265→  /** Number of tasks completed since the given time */
   266→  tasks_completed: number;
   267→  /** Number of tasks started since the given time */
   268→  tasks_started: number;
   269→  /** References of completed tasks */
   270→  completed_refs: string[];
   271→}
   272→
